      id: null,
      fg_code: '',
      product_name: '',
      unit_id: 3,
      category_id: '',
      selling_price: 0,
      minimum_stock: 0,
      reorder_level: 0,
      maximum_stock: 0,
      hsn_code: '',
      description: '',
